const diffImagesWithPython = async ({ referencePath = "", candidatePath = "", diffPath = "" } = {}) => {
  const script = `python3 - <<'PY'
from PIL import Image, ImageChops
import json
import os

ref = ${JSON.stringify(referencePath)}
cand = ${JSON.stringify(candidatePath)}
diff_path = ${JSON.stringify(diffPath)}

ref_img = Image.open(ref).convert("RGBA")
cand_img = Image.open(cand).convert("RGBA")
width = max(ref_img.width, cand_img.width)
height = max(ref_img.height, cand_img.height)

def pad(image):
    canvas = Image.new("RGBA", (width, height), (255, 255, 255, 0))
    canvas.paste(image, (0, 0))
    return canvas

ref_pad = pad(ref_img)
cand_pad = pad(cand_img)
diff = ImageChops.difference(ref_pad, cand_pad)
os.makedirs(os.path.dirname(diff_path), exist_ok=True)
diff.save(diff_path)

bbox = diff.getbbox()
diff_pixels = 0
if bbox:
    for pixel in diff.getdata():
        if pixel != (0, 0, 0, 0):
            diff_pixels += 1

total = max(1, width * height)
diff_ratio = diff_pixels / total
print(json.dumps({
    "width": width,
    "height": height,
    "diffPixels": diff_pixels,
    "totalPixels": total,
    "diffRatio": round(diff_ratio, 6),
    "similarity": round(1 - diff_ratio, 6)
}))
PY`;
  const { stdout } = await runShell(script, { cwd: ROOT });
  return parseJsonLine(stdout) || {
    width: 0,
    height: 0,
    diffPixels: 0,
    totalPixels: 0,
    diffRatio: 1,
    similarity: 0,
  };
};

const mergeSlotPools = (target = {}, source = {}) => ({
  text: [...(Array.isArray(target?.text) ? target.text : []), ...(Array.isArray(source?.text) ? source.text : [])],
  image: [...(Array.isArray(target?.image) ? target.image : []), ...(Array.isArray(source?.image) ? source.image : [])],
  link: [...(Array.isArray(target?.link) ? target.link : []), ...(Array.isArray(source?.link) ? source.link : [])],
});

const emptySlotPool = () => ({ text: [], image: [], link: [] });

const TEMPLATE_FIDELITY_SKIP_PATH_RE =
  /(^|\.)(theme|palette|layoutrules|tokens|fontfamilies|fontheading|fontbody|motion|mode|primarycolor)(\.|$)/i;

const isTemplateFidelityRichMarkup = (value = "") => {
  const raw = String(value || "").trim();
  if (!raw) return false;
  if (raw.length > 20000) return true;
  return /<!doctype html|<html\b|<head\b|<body\b|<svg\b|<style\b/i.test(raw);
};

const shouldSkipTemplateFidelitySlotPath = (pathValue = "") => {
  const normalized = String(pathValue || "").trim().toLowerCase();
  if (!normalized) return false;
  return TEMPLATE_FIDELITY_SKIP_PATH_RE.test(normalized);
};

const extractSlotPoolFromValue = (value, key = "", pool = emptySlotPool(), pathPrefix = "") => {
  const pathValue = pathPrefix ? `${pathPrefix}.${key}` : key;
  if (shouldSkipTemplateFidelitySlotPath(pathValue)) {
    return pool;
  }
  if (Array.isArray(value)) {
    value.forEach((entry, index) => extractSlotPoolFromValue(entry, `[${index}]`, pool, pathValue));
    return pool;
  }
  if (value && typeof value === "object") {
    Object.entries(value).forEach(([childKey, childValue]) =>
      extractSlotPoolFromValue(childValue, childKey, pool, pathValue)
    );
    return pool;
  }
  if (typeof value !== "string" && typeof value !== "number" && typeof value !== "boolean") {
    return pool;
  }
  if (shouldSkipEditableField(key) || isTemplateFidelityRichMarkup(value)) return pool;
  const fieldType = inferEditableFieldType(key, value);
  if (!["text", "image", "link"].includes(fieldType)) return pool;
  const normalized = String(value ?? "").trim();
  if (!normalized) return pool;
  pool[fieldType].push(normalized);
  return pool;
};

const extractSlotPoolsFromPayload = (payload = {}) => {
  const globalPool = emptySlotPool();
  const byKind = new Map();
  const pages = Array.isArray(payload?.pages) ? payload.pages : [];
  for (const page of pages) {
    const content = Array.isArray(page?.data?.content) ? page.data.content : [];
    for (const section of content) {
      const kind = normalizeSectionKind(inferSectionKindFromPayloadSection(section) || "generic") || "generic";
      const sectionPool = byKind.get(kind) || emptySlotPool();
      extractSlotPoolFromValue(section?.props && typeof section.props === "object" ? section.props : {}, "", sectionPool);
      byKind.set(kind, sectionPool);
      extractSlotPoolFromValue(section?.props && typeof section.props === "object" ? section.props : {}, "", globalPool);
    }
  }
  return { global: globalPool, byKind };
};

const normalizeTemplateFidelityPayloadDocument = (value = null) => {
  if (value && typeof value === "object" && Array.isArray(value?.pages)) return value;
  if (value && typeof value === "object" && value?.payload && Array.isArray(value.payload?.pages)) return value.payload;
  return null;
};

const resolveTemplateFidelityCasePath = (candidate = "", baseDir = ROOT) => {
  const raw = String(candidate || "").trim();
  if (!raw) return "";
  return path.isAbsolute(raw) ? raw : path.resolve(baseDir, raw);
};

const loadTemplateFidelityCaseInput = async ({ options = {}, defaultSource = null } = {}) => {
  const configuredPath = String(options?.templateFidelityCaseFile || "").trim();
  const configuredCaseId = String(options?.templateFidelityCaseId || "").trim();
  if (!configuredPath) {
    return {
      source: "bundle-first-artifact",
      sourceCaseId: String(defaultSource?.artifact?.caseId || "").trim(),
      caseFile: "",
      payload: defaultSource?.exported?.payload || {},
    };
  }
  const resolvedPath = resolveTemplateFidelityCasePath(configuredPath, ROOT);
  const raw = JSON.parse(await fs.readFile(resolvedPath, "utf8"));
  const directPayload = normalizeTemplateFidelityPayloadDocument(raw);
  if (directPayload) {
    return {
      source: "payload-file",
      sourceCaseId:
        configuredCaseId ||
        String(raw?.caseId || raw?.siteKey || raw?.siteId || "").trim() ||
        path.basename(resolvedPath, path.extname(resolvedPath)),
      caseFile: resolvedPath,
      payload: directPayload,
    };
  }
  const artifacts = Array.isArray(raw?.artifacts)
    ? raw.artifacts
    : raw && typeof raw === "object" && (raw?.payloadPath || raw?.caseId)
      ? [raw]
      : [];
  if (!artifacts.length) {
    throw new Error(
      `[template-factory] unsupported template fidelity case input: ${resolvedPath}. Expected a payload JSON or bundle JSON with artifacts[].payloadPath.`
    );
  }
  const artifact =
    artifacts.find((entry) => String(entry?.caseId || "").trim() === configuredCaseId) ||
    artifacts.find((entry) => String(entry?.siteId || "").trim() === configuredCaseId) ||
    artifacts[0];
  const payloadPath = resolveTemplateFidelityCasePath(
    String(artifact?.payloadPath || artifact?.payloadFile || "").trim(),
    path.dirname(resolvedPath)
  );
  if (!payloadPath) {
    throw new Error(
      `[template-factory] template fidelity case input ${resolvedPath} is missing payloadPath for ${configuredCaseId || artifact?.caseId || "selected artifact"}.`
    );
  }
  const payloadRaw = JSON.parse(await fs.readFile(payloadPath, "utf8"));
  const payload = normalizeTemplateFidelityPayloadDocument(payloadRaw);
  if (!payload) {
    throw new Error(`[template-factory] template fidelity case payload is invalid: ${payloadPath}`);
  }
  return {
    source: "bundle-artifact-payload",
    sourceCaseId:
      String(artifact?.caseId || "").trim() ||
      configuredCaseId ||
      path.basename(payloadPath, path.extname(payloadPath)),
    caseFile: resolvedPath,
    payloadPath,
    payload,
  };
};

const TEMPLATE_FIDELITY_BG_KEY_RE = /(background|bg|surface|fill|overlay|panel|canvas)/i;
const TEMPLATE_FIDELITY_TEXT_KEY_RE =
  /(text|label|title|subtitle|body|copy|caption|menu|nav|link|item|foreground|fg|icon|legal|meta|color)/i;

const dedupeTemplateFidelityColors = (values = []) =>
  Array.from(
    new Set(
      (Array.isArray(values) ? values : [])
        .map((entry) => String(entry || "").trim())
        .filter((entry) => entry && penColorLuminance(entry) && !isPenTransparentColorValue(entry))
    )
  );

const collectTemplateFidelityColorHints = (value, key = "", report = null) => {
  const target =
    report ||
    {
      backgrounds: [],
      foregrounds: [],
    };
  if (Array.isArray(value)) {
    value.forEach((entry) => collectTemplateFidelityColorHints(entry, key, target));
    return target;
  }
  if (value && typeof value === "object") {
    Object.entries(value).forEach(([childKey, childValue]) =>
      collectTemplateFidelityColorHints(childValue, childKey, target)
    );
    return target;
  }
  const color = String(value || "").trim();
  if (!color || !penColorLuminance(color) || isPenTransparentColorValue(color)) return target;
  const token = String(key || "").trim().toLowerCase();
  if (TEMPLATE_FIDELITY_BG_KEY_RE.test(token) && !/(text|label|title|body|copy|link|fg|foreground|icon)/i.test(token)) {
    target.backgrounds.push(color);
    return target;
  }
  if (TEMPLATE_FIDELITY_TEXT_KEY_RE.test(token)) {
    target.foregrounds.push(color);
  }
  return target;
};

const auditPayloadNavFooterContrast = ({ payload = {}, minContrast = 4.5 } = {}) => {
  const globalTheme = payload?.theme && typeof payload.theme === "object" ? payload.theme : {};
  const sectionRows = [];
  const pages = Array.isArray(payload?.pages) ? payload.pages : [];
  for (const page of pages) {
    const pagePath = normalizeTemplatePagePath(page?.path || "/");
    const pageTheme =
      page?.data?.root?.props?.theme && typeof page.data.root.props.theme === "object"
        ? page.data.root.props.theme
        : globalTheme;
    const palette = pageTheme?.palette && typeof pageTheme.palette === "object" ? pageTheme.palette : {};
    const sections = Array.isArray(page?.data?.content) ? page.data.content : [];
    for (const section of sections) {
      const kind = normalizeSectionKind(inferSectionKindFromPayloadSection(section) || "") || "";
      if (!["navigation", "footer"].includes(kind)) continue;
      const hints = collectTemplateFidelityColorHints(section?.props && typeof section.props === "object" ? section.props : {});
      const backgrounds = dedupeTemplateFidelityColors([palette.bg, palette.neutral, ...hints.backgrounds]);
      const foregrounds = dedupeTemplateFidelityColors([
        palette.text,
        palette.textSecondary,
        palette.primary,
        palette.accent,
        ...hints.foregrounds,
      ]).filter((color) => !backgrounds.includes(color));
      const background = backgrounds[0] || "";
      const evaluatedForegrounds = foregrounds
        .map((color) => ({
          color,
          contrast: Number(penColorContrastRatio(background, color).toFixed(3)),
        }))
        .sort((left, right) => left.contrast - right.contrast);
      const weakest = evaluatedForegrounds[0] || null;
      sectionRows.push({
        pagePath,
        sectionKey: String(section?._key || section?.props?.id || `${kind}-${pagePath}`),
        kind,
        background,
        minimumContrast: weakest ? weakest.contrast : null,
        weakestForeground: weakest?.color || "",
        evaluatedForegrounds,
        passed: weakest ? weakest.contrast >= minContrast : false,
        reason: weakest ? "" : "insufficient_color_data",
      });
    }
  }
  const failedSections = sectionRows.filter((row) => !row.passed);
  const minimumObservedContrast =
    sectionRows.length > 0
      ? Number(
          Math.min(
            ...sectionRows.map((row) => (Number.isFinite(Number(row.minimumContrast)) ? Number(row.minimumContrast) : Infinity))
          ).toFixed(3)
        )
      : null;
  return {
    minContrastThreshold: Number(minContrast),
    auditedSectionCount: sectionRows.length,
    failedSectionCount: failedSections.length,
    minimumObservedContrast:
      minimumObservedContrast === Infinity || Number.isNaN(minimumObservedContrast) ? null : minimumObservedContrast,
    sections: sectionRows,
    passed: failedSections.length === 0,
  };
};

const nextSlotValue = ({ fieldType = "", sectionPool = null, globalPool = null, state = null, fallback = "" } = {}) => {
  const type = String(fieldType || "").trim();
  const nextFromPool = (pool, scope) => {
    const values = Array.isArray(pool?.[type]) ? pool[type] : [];
    if (!values.length) return null;
    if (!state[scope]) state[scope] = {};
    const index = Number(state[scope][type] || 0);
    const next = values[index % values.length];
    state[scope][type] = index + 1;
    return next;
  };
  return nextFromPool(sectionPool, "section") ?? nextFromPool(globalPool, "global") ?? fallback;
};

const applySlotPoolToValue = (value, { sectionPool = null, globalPool = null, state = null, key = "", pathPrefix = "" } = {}) => {
  const pathValue = pathPrefix ? `${pathPrefix}.${key}` : key;
  if (shouldSkipTemplateFidelitySlotPath(pathValue)) {
    return cloneJson(value);
  }
  if (Array.isArray(value)) {
    return value.map((entry, index) =>
      applySlotPoolToValue(entry, { sectionPool, globalPool, state, key: `[${index}]`, pathPrefix: pathValue })
    );
  }
  if (value && typeof value === "object") {
    const out = {};
    Object.entries(value).forEach(([childKey, childValue]) => {
      out[childKey] = applySlotPoolToValue(childValue, {
        sectionPool,
        globalPool,
        state,
        key: childKey,
        pathPrefix: pathValue,
      });
    });
    return out;
  }
  if (
    (typeof value !== "string" && typeof value !== "number" && typeof value !== "boolean") ||
    shouldSkipEditableField(key) ||
    isTemplateFidelityRichMarkup(value)
  ) {
    return value;
  }
  const fieldType = inferEditableFieldType(key, value);
  if (!["text", "image", "link"].includes(fieldType)) return value;
  const fallback = String(value ?? "");
  return nextSlotValue({
    fieldType,
    sectionPool,
    globalPool,
    state,
    fallback,
  });
};

const resolveReplaySectionsForPageSpec = ({ profile = {}, pageSpec = {} } = {}) => {
  const explicitSections = Array.isArray(pageSpec?.sections) ? pageSpec.sections : [];
  if (explicitSections.length) return explicitSections;
  const requiredKinds = Array.isArray(pageSpec?.requiredCategories) ? pageSpec.requiredCategories : [];
  return requiredKinds
    .map((kind, index) => ({
      kind,
      ordinal: index + 1,
      source: pageSpec?.templates?.[kind] ? "page" : "profile",
      block: pageSpec?.templates?.[kind] || profile?.templates?.[kind] || null,
    }))
    .filter((entry) => entry?.block);
};

const buildReplayPayloadFromProfile = ({ profile = {}, baselinePayload = {}, sharedSlotPools = null } = {}) => {
  const baselinePages = new Map(
    (Array.isArray(baselinePayload?.pages) ? baselinePayload.pages : []).map((page) => [
      normalizeTemplatePagePath(page?.path || "/"),
      page,
    ])
  );
  const globalPool = sharedSlotPools?.global || emptySlotPool();
  const pages = (Array.isArray(profile?.pageSpecs) ? profile.pageSpecs : []).map((pageSpec) => {
    const pagePath = normalizeTemplatePagePath(pageSpec?.path || "/");
    const baselinePage = baselinePages.get(pagePath) || null;
    const baselineSections = Array.isArray(baselinePage?.data?.content) ? baselinePage.data.content : [];
    const sections = resolveReplaySectionsForPageSpec({ profile, pageSpec });
    const content = sections.map((section, index) => {
      const block = cloneJson(section?.block || {});
      const baselineSection = baselineSections[index] || null;
      const kind = normalizeSectionKind(section?.kind || "") || "generic";
      const sectionPool = sharedSlotPools?.byKind instanceof Map ? sharedSlotPools.byKind.get(kind) || emptySlotPool() : emptySlotPool();
      const state = { section: {}, global: {} };
      const nextProps = applySlotPoolToValue(block?.props && typeof block.props === "object" ? block.props : {}, {
        sectionPool,
        globalPool,
        state,
        key: "",
      });
      if (!String(nextProps?.id || "").trim()) {
        nextProps.id = `${kind}-${index + 1}`;
      }
      return {
        type: String(block?.type || "").trim(),
        _key: String(baselineSection?._key || block?._key || nextProps.id || `${kind}-${index + 1}`),
        kind,
        props: nextProps,
        ...(baselineSection?.meta && typeof baselineSection.meta === "object" ? { meta: cloneJson(baselineSection.meta) } : {}),
      };
    });
    const baselineRootProps =
      baselinePage?.data?.root?.props && typeof baselinePage.data.root.props === "object"
        ? cloneJson(baselinePage.data.root.props)
        : {};
    return {
      path: pagePath,
      name: String(pageSpec?.name || "").trim() || formatTemplatePageName(pagePath),
      data: {
        root: {
          props: {
            ...baselineRootProps,
            title: String(baselineRootProps?.title || pageSpec?.name || formatTemplatePageName(pagePath)),
          },
        },
        content,
      },
    };
  });
  const theme =
    baselinePayload?.theme && typeof baselinePayload.theme === "object"
      ? cloneJson(baselinePayload.theme)
      : pages[0]?.data?.root?.props?.theme && typeof pages[0].data.root.props.theme === "object"
        ? cloneJson(pages[0].data.root.props.theme)
        : {};
  return {
    components: Array.isArray(baselinePayload?.components) ? cloneJson(baselinePayload.components) : [],
    pages,
    theme,
  };
};

const summarizeStructureSection = (section = {}) => ({
  key: String(section?._key || section?.props?.id || ""),
  type: String(section?.type || "").trim(),
  kind: normalizeSectionKind(inferSectionKindFromPayloadSection(section) || "") || "",
});

const buildPayloadStructureDiffReport = ({ expectedPayload = {}, actualPayload = {} } = {}) => {
  const expectedPages = Array.isArray(expectedPayload?.pages) ? expectedPayload.pages : [];
  const actualPages = Array.isArray(actualPayload?.pages) ? actualPayload.pages : [];
  const actualByPath = new Map(
    actualPages.map((page) => [normalizeTemplatePagePath(page?.path || "/"), page])
  );
  const criticalKinds = new Set(["navigation", "hero", "footer"]);
  let matchedPages = 0;
  let expectedSectionsTotal = 0;
  let matchedSections = 0;
  let expectedCriticalBlocks = 0;
  let matchedCriticalBlocks = 0;
  const pages = expectedPages.map((expectedPage) => {
    const pathValue = normalizeTemplatePagePath(expectedPage?.path || "/");
    const actualPage = actualByPath.get(pathValue) || null;
    const expectedSections = (Array.isArray(expectedPage?.data?.content) ? expectedPage.data.content : []).map(summarizeStructureSection);
    const actualSections = (Array.isArray(actualPage?.data?.content) ? actualPage.data.content : []).map(summarizeStructureSection);
    const max = Math.max(expectedSections.length, actualSections.length);
    const rows = [];
    let pageMatches = 0;
    let pageCriticalExpected = 0;
    let pageCriticalMatched = 0;
    for (let index = 0; index < max; index += 1) {
      const expected = expectedSections[index] || null;
      const actual = actualSections[index] || null;
      const sameKind = expected?.kind && actual?.kind && expected.kind === actual.kind;
      const sameType = expected?.type && actual?.type && expected.type === actual.type;
      const matched = Boolean(expected && actual && sameKind && sameType);
      const mismatches = [];
      if (!expected || !actual) mismatches.push("missing_section");
      else {
        if (!sameKind) mismatches.push("kind");
        if (!sameType) mismatches.push("type");
      }
      if (expected) {
        expectedSectionsTotal += 1;
        if (criticalKinds.has(expected.kind)) {
          expectedCriticalBlocks += 1;
          pageCriticalExpected += 1;
        }
      }
      if (matched) {
        matchedSections += 1;
        pageMatches += 1;
        if (expected && criticalKinds.has(expected.kind)) {
          matchedCriticalBlocks += 1;
          pageCriticalMatched += 1;
        }
      }
      rows.push({
        index,
        status: matched ? "match" : "mismatch",
        mismatches,
        expected,
        actual,
      });
    }
    if (actualPage) matchedPages += 1;
    return {
      path: pathValue,
      expectedSectionCount: expectedSections.length,
      actualSectionCount: actualSections.length,
      matchedSectionCount: pageMatches,
      criticalBlockMatchedCount: pageCriticalMatched,
      criticalBlockExpectedCount: pageCriticalExpected,
      rows,
    };
  });
  const pageHitRate = expectedPages.length > 0 ? matchedPages / expectedPages.length : 1;
  const sectionHitRate = expectedSectionsTotal > 0 ? matchedSections / expectedSectionsTotal : 1;
  const blockHitRate = expectedCriticalBlocks > 0 ? matchedCriticalBlocks / expectedCriticalBlocks : 1;
  const similarity = Number((pageHitRate * 0.35 + sectionHitRate * 0.4 + blockHitRate * 0.25).toFixed(6));
  return {
    generatedAt: new Date().toISOString(),
    expectedPageCount: expectedPages.length,
    actualPageCount: actualPages.length,
    matchedPageCount: matchedPages,
    expectedSectionCount: expectedSectionsTotal,
    matchedSectionCount: matchedSections,
    expectedCriticalBlockCount: expectedCriticalBlocks,
    matchedCriticalBlockCount: matchedCriticalBlocks,
    pageHitRate: Number(pageHitRate.toFixed(6)),
    sectionHitRate: Number(sectionHitRate.toFixed(6)),
    blockHitRate: Number(blockHitRate.toFixed(6)),
    similarity,
    pages,
  };
};

const collectContentSlotDiff = ({ expected = null, actual = null, key = "", pathPrefix = "", report = null } = {}) => {
  const reportRef =
    report ||
    {
      allowedChanges: { text: 0, image: 0, link: 0 },
      illegalChanges: [],
    };
  const pathValue = pathPrefix ? `${pathPrefix}.${key}` : key;
  if (Array.isArray(expected) || Array.isArray(actual)) {
    if (!Array.isArray(expected) || !Array.isArray(actual) || expected.length !== actual.length) {
      reportRef.illegalChanges.push({ path: pathValue, reason: "array_length_changed" });
      return reportRef;
    }
    expected.forEach((entry, index) =>
      collectContentSlotDiff({
        expected: entry,
        actual: actual[index],
        key: `[${index}]`,
        pathPrefix: pathValue,
        report: reportRef,
      })
    );
    return reportRef;
  }
  if ((expected && typeof expected === "object") || (actual && typeof actual === "object")) {
    if (!expected || !actual || typeof expected !== "object" || typeof actual !== "object") {
      reportRef.illegalChanges.push({ path: pathValue, reason: "shape_changed" });
      return reportRef;
    }
    const keys = new Set([...Object.keys(expected), ...Object.keys(actual)]);
    for (const childKey of keys) {
      collectContentSlotDiff({
        expected: expected?.[childKey],
        actual: actual?.[childKey],
        key: childKey,
        pathPrefix: pathValue,
        report: reportRef,
      });
    }
    return reportRef;
  }
  if (expected === actual) return reportRef;
  const fieldType = inferEditableFieldType(key, expected);
  if (!shouldSkipEditableField(key) && ["text", "image", "link"].includes(fieldType)) {
    reportRef.allowedChanges[fieldType] += 1;
    return reportRef;
  }
  reportRef.illegalChanges.push({
    path: pathValue,
    reason: "non_slot_value_changed",
    expected,
    actual,
  });
  return reportRef;
};

const filterRunLibraryByProfileIds = (runLibrary = {}, profileIds = new Set()) => {
  const keep = new Set(Array.isArray(profileIds) ? profileIds : Array.from(profileIds || []));
  const profiles = (Array.isArray(runLibrary?.profiles) ? runLibrary.profiles : []).filter((profile) =>
    keep.has(String(profile?.id || ""))
  );
  const templateExclusiveComponents = (Array.isArray(runLibrary?.templateExclusiveComponents)
    ? runLibrary.templateExclusiveComponents
    : []
  ).filter((component) => keep.has(String(component?.templateExclusive?.siteId || "")));
  const templateBlockCatalog = (Array.isArray(runLibrary?.templateBlockCatalog) ? runLibrary.templateBlockCatalog : []).filter((entry) =>
    keep.has(String(entry?.profileId || ""))
  );
  const templateGenerationContracts = (Array.isArray(runLibrary?.templateGenerationContracts)
    ? runLibrary.templateGenerationContracts
    : []
  ).filter((entry) => keep.has(String(entry?.profileId || "")));
  return {
    ...runLibrary,
    profileCount: profiles.length,
    profiles,
    templateExclusiveComponentCount: templateExclusiveComponents.length,
    templateExclusiveComponents,
    templateBlockCatalogCount: templateBlockCatalog.length,
    templateBlockCatalog,
    templateGenerationContractsCount: templateGenerationContracts.length,
    templateGenerationContracts,
  };
};

const buildCrawledPageAssetPack = async ({
  siteId,
  crawl,
  ingestDir,
  captureLimit = 12,
  screenshotTimeoutMs = 90000,
  screenshotSemaphore = null,
  logPrefix = "[template-factory]",
}) => {
  if (!crawl?.enabled) return null;

  const SKIP_ROUTE_PATTERNS = [
    /(^|\/)login(\/|$)/i,
    /(^|\/)auth(\/|$)/i,
    /(^|\/)signin(\/|$)/i,
    /(^|\/)signup(\/|$)/i,
    /(^|\/)account(\/|$)/i,
    /(^|\/)cart(\/|$)/i,
    /(^|\/)checkout(\/|$)/i,
    /(^|\/)orders?(\/|$)/i,
    /(^|\/)policies(\/|$)/i,
    /(^|\/)privacy(\/|$)/i,
    /(^|\/)terms(\/|$)/i,
    /(^|\/)legal(\/|$)/i,
    /(^|\/)cookie(?:s|-policy)?(\/|$)/i,
  ];

  const pagesDir = path.join(ingestDir, "pages");
  await ensureDir(pagesDir);
  const filterStats = {
    totalCandidates: Array.isArray(crawl?.pages) ? crawl.pages.length : 0,
    excludedByErrorOrStatus: 0,
    excludedByLowQualityTitle: 0,
    excludedByRoutePolicy: 0,
    excludedByDownloadPolicy: 0,
    excludedByTemplateDedupe: 0,
  };

  const successfulPagesRaw = [];
  for (const page of Array.isArray(crawl?.pages) ? crawl.pages : []) {
    if (!page || page.error || !isSuccessfulCrawlStatus(page.status)) {
      filterStats.excludedByErrorOrStatus += 1;
      continue;
    }
    const routePath = routePathFromUrl(page.url);
    if (!routePath) {
      filterStats.excludedByRoutePolicy += 1;
      continue;
    }
    if (routePath !== "/" && isLowQualityPageTitle(page.title)) {
      filterStats.excludedByLowQualityTitle += 1;
      continue;
    }
    const routeFiltered = SKIP_ROUTE_PATTERNS.some((pattern) => pattern.test(routePath));
    if (routeFiltered) {
      filterStats.excludedByRoutePolicy += 1;
      continue;
    }
    if (isLikelyDownloadPath(routePath)) {
      filterStats.excludedByDownloadPolicy += 1;
      continue;
    }
    successfulPagesRaw.push(page);
  }

  const successfulPages = successfulPagesRaw;

  console.log(
    `${logPrefix} crawl asset filter stats: total=${filterStats.totalCandidates}, kept=${successfulPages.length}, excluded=status_or_error:${filterStats.excludedByErrorOrStatus}, low_quality_title:${filterStats.excludedByLowQualityTitle}, route_policy:${filterStats.excludedByRoutePolicy}, download_policy:${filterStats.excludedByDownloadPolicy}, template_dedupe:${filterStats.excludedByTemplateDedupe}`
  );
  if (!successfulPages.length) {
    const emptyPack = {
      generatedAt: new Date().toISOString(),
      entryUrl: crawl?.entryUrl || "",
      pageCount: 0,
      pages: [],
    };
    const manifestPath = path.join(pagesDir, "pages.json");
    await fs.writeFile(manifestPath, JSON.stringify(emptyPack, null, 2));
    return { manifestPath, pages: [], byPath: new Map() };
  }

  const pages = [];
  const byPath = new Map();

  const limit = Math.max(0, Math.floor(Number(captureLimit) || 0));
  const total = successfulPages.length;
  const routeCapturePriority = (routePath) => {
    if (!routePath || routePath === "/") return 0;
    if (/^\/contact(?:\/|$)/i.test(routePath)) return 1;
    if (/^\/blogs\/[^/]+\/[^/]+/i.test(routePath)) return 2;
    if (/^\/collections\/[^/]+\/products\/[^/]+/i.test(routePath) || /^\/products\/[^/]+/i.test(routePath)) return 3;
    if (/^\/blogs(?:\/|$)/i.test(routePath)) return 4;
    if (/^\/collections(?:\/|$)/i.test(routePath)) return 5;
    return 9;
  };
  const captureRouteSet = (() => {
    if (limit <= 0) return new Set();
    const ranked = successfulPages
      .map((page, index) => {
        const routePath = routePathFromUrl(page?.url);
        return {
          index,
          routePath,
          depth: Number(page?.depth || 0),
          priority: routeCapturePriority(routePath),
        };
      })
      .filter((entry) => Boolean(entry.routePath))
      .sort((a, b) => {
        if (a.priority !== b.priority) return a.priority - b.priority;
        if (a.depth !== b.depth) return a.depth - b.depth;
        return a.index - b.index;
      });
    return new Set(ranked.slice(0, limit).map((entry) => entry.routePath));
  })();

  for (const [index, page] of successfulPages.entries()) {
    const routePath = routePathFromUrl(page.url);
    if (!routePath) continue;
    if (byPath.has(routePath)) continue;
    const routeSlug = routeSlugFromPath(routePath) || `page-${index + 1}`;
    const pageDir = path.join(pagesDir, routeSlug);
    await ensureDir(pageDir);

    const desktopPath = path.join(pageDir, "desktop.auto.png");
    const mobilePath = path.join(pageDir, "mobile.auto.png");
    const shouldCapture = captureRouteSet.has(routePath);
    console.log(
      `${logPrefix} page asset ${index + 1}/${total} route=${routePath} capture=${shouldCapture ? "yes" : "no"}`
    );
    const desktopShot = shouldCapture
      ? await runWithSemaphore(screenshotSemaphore, () =>
          captureScreenshotSafe({
            url: page.url,
            outPath: desktopPath,
            mobile: false,
            timeoutMs: screenshotTimeoutMs,
          })
        )
      : null;
    const mobileShot = shouldCapture
      ? await runWithSemaphore(screenshotSemaphore, () =>
          captureScreenshotSafe({
            url: page.url,
            outPath: mobilePath,
            mobile: true,
            timeoutMs: screenshotTimeoutMs,
          })
        )
      : null;
    const published = await publishCrawledPageAssets({
      siteId,
      routeSlug,
      desktopSource: desktopShot,
      mobileSource: mobileShot,
    });
    const pageVisualSignature = await extractImageVisualSignature(desktopShot || "");

    const summary = {
      title: String(page.title || "").trim(),
      h1: Array.isArray(page.h1) ? page.h1 : [],
      h2: Array.isArray(page.h2) ? page.h2 : [],
      links: Array.isArray(page.links) ? page.links : [],
      images: Array.isArray(page.images) ? page.images : [],
      footerLinks: dedupeLinkItems(Array.isArray(page.footerLinks) ? page.footerLinks : [], 24),
      navMenuDepth: Number(page.navMenuDepth || 1),
      heroPresentation: normalizeHeroPresentation(page.heroPresentation),
      heroCarousel: normalizeHeroCarousel(page.heroCarousel),
      htmlChars: Number(page.htmlChars || 0),
      internalLinksCount: Number(page.internalLinksCount || 0),
      status: Number(page.status || 0),
      visualSignature: pageVisualSignature || null,
    };
    const assetContext = buildPageAssetContext({
      images: summary.images,
      desktopUrl: published.desktopUrl || "",
      mobileUrl: published.mobileUrl || "",
    });

    const pageRecord = {
      path: routePath,
      name: routeNameFromPath(routePath),
      url: String(page.url || "").trim(),
      depth: Number(page.depth || 0),
      status: Number(page.status || 0),
      from: String(page.from || "").trim(),
      summary,
      visualSignature: pageVisualSignature || null,
      screenshots: {
        desktopPath: desktopShot || null,
        mobilePath: mobileShot || null,
      },
      publishedAssets: published,
      assetContext,
    };
    await fs.writeFile(path.join(pageDir, "summary.json"), JSON.stringify(pageRecord, null, 2));
    pages.push(pageRecord);
    byPath.set(routePath, pageRecord);
  }

  const payload = {
    generatedAt: new Date().toISOString(),
    entryUrl: crawl?.entryUrl || "",
    homePath: pages[0]?.path || "/",
    pageCount: pages.length,
    filterStats,
    pages,
  };
  const manifestPath = path.join(pagesDir, "pages.json");
  await fs.writeFile(manifestPath, JSON.stringify(payload, null, 2));
  return { manifestPath, pages, byPath, homePath: payload.homePath };
};

const mergeCrawlAssetPacks = ({ primary = null, fallback = null } = {}) => {
  const toRows = (pack) => (Array.isArray(pack?.pages) ? pack.pages : []);
  const merged = new Map();
  for (const row of toRows(fallback)) {
    const pathValue = normalizeTemplatePagePath(row?.path || routePathFromUrl(row?.url || "") || "/");
    if (!pathValue || merged.has(pathValue)) continue;
    merged.set(pathValue, row);
  }
  for (const row of toRows(primary)) {
    const pathValue = normalizeTemplatePagePath(row?.path || routePathFromUrl(row?.url || "") || "/");
    if (!pathValue) continue;
    merged.set(pathValue, row);
  }
  const pages = Array.from(merged.values());
  return {
    ...(primary && typeof primary === "object" ? primary : {}),
    ...(fallback && typeof fallback === "object" ? { reusedFromRunId: fallback.reusedFromRunId || "" } : {}),
    pages,
    byPath: new Map(
      pages.map((row) => [normalizeTemplatePagePath(row?.path || routePathFromUrl(row?.url || "") || "/"), row])
    ),
    homePath:
      String(primary?.homePath || "").trim() ||
      String(fallback?.homePath || "").trim() ||
      normalizeTemplatePagePath(pages[0]?.path || "/"),
  };
};

const loadFallbackCrawlAssetPack = async ({ siteId, siteUrl = "", currentRunId = "", minPages = 0 } = {}) => {
  const requiredMin = Math.max(1, Math.floor(Number(minPages || 0) || 0));
  if (!siteId || requiredMin <= 0) return null;
  const normalizeOrigin = (value) => {
    const raw = String(value || "").trim();
    if (!raw) return "";
    try {
      return new URL(raw).origin;
    } catch {
      return "";
    }
  };
  const expectedOrigin = normalizeOrigin(siteUrl);
  let entries = [];
  try {
    entries = await fs.readdir(RUNS_DIR, { withFileTypes: true });
  } catch {
    return null;
  }
  const candidates = entries
    .filter((entry) => entry?.isDirectory?.())
    .map((entry) => String(entry.name || "").trim())
    .filter((name) => name && name !== currentRunId)
    .sort((a, b) => b.localeCompare(a));
  for (const runId of candidates) {
    const manifestPath = path.join(RUNS_DIR, runId, "sites", siteId, "ingest", "pages", "pages.json");
    try {
      const raw = await fs.readFile(manifestPath, "utf8");
      const parsed = JSON.parse(raw);
      const rows = Array.isArray(parsed?.pages) ? parsed.pages : [];
      if (expectedOrigin) {
        const fallbackOrigin = normalizeOrigin(parsed?.entryUrl || rows[0]?.url || "");
        if (fallbackOrigin && fallbackOrigin !== expectedOrigin) continue;
      }
      const validRows = rows.filter((row) =>
        isSuccessfulCrawlStatus(Number(row?.status || row?.summary?.status || 0))
      );
      if (validRows.length < requiredMin) continue;
      return {
        manifestPath,
        pages: validRows,
        byPath: new Map(
          validRows.map((row) => [
            normalizeTemplatePagePath(row?.path || routePathFromUrl(row?.url || "") || "/"),
            row,
          ])
        ),
        homePath: normalizeTemplatePagePath(parsed?.homePath || validRows[0]?.path || "/"),
        reusedFromRunId: runId,
      };
    } catch {
      continue;
    }
  }
  return null;
};

const summaryTextList = (value) =>
  (Array.isArray(value) ? value : [])
    .map((entry) => String(entry || "").trim())
    .filter(Boolean);

const isLikelyBlockedHtmlSummary = (summary = null) => {
  const row = summary && typeof summary === "object" ? summary : {};
  const title = String(row?.title || "").trim();
  const h1 = summaryTextList(row?.h1);
  const h2 = summaryTextList(row?.h2);
  const links = summaryTextList(row?.links);
  const images = dedupeUrls(Array.isArray(row?.images) ? row.images : [], 120);
  const status = Number(row?.status || 0);
  const htmlChars = Number(row?.htmlChars || 0);
  const combined = [title, ...h1, ...h2].join(" ").trim();
  const titleLowQuality =
    isLowQualityPageTitle(title) || isLowQualityTextSignal(title, { allowSingleWord: true });
  const antiCrawlText =
    hasAntiCrawlSignals(combined) ||
    /请稍候|稍候|just a moment|verify(?:ing)? you are human|checking your browser|connection needs to be verified/i.test(
      combined
    );
  const sparseHeadings = h1.length === 0 && h2.length === 0;
  const sparseLinks = links.length <= 1;
  const sparseImages = images.length <= 1;
  const blockedStatus = status === 301 || status === 302 || status === 303 || status === 307 || status === 308 || status === 401 || status === 403 || status === 429;
  const lowHtmlDensity = htmlChars > 0 && htmlChars < 15000;
  if (antiCrawlText) return true;
  if (titleLowQuality && sparseHeadings && sparseLinks) return true;
  if ((sparseHeadings && sparseLinks && sparseImages) && (blockedStatus || lowHtmlDensity)) return true;
  return false;
};

const isUsableHistoricalHtmlSummary = (summary = null) => {
  const row = summary && typeof summary === "object" ? summary : {};
  if (isLikelyBlockedHtmlSummary(row)) return false;
  const title = String(row?.title || "").trim();
  const h1Count = summaryTextList(row?.h1).length;
  const h2Count = summaryTextList(row?.h2).length;
  const linksCount = summaryTextList(row?.links).length;
  const imagesCount = Array.isArray(row?.images) ? row.images.length : 0;
  const titleLowQuality =
    !title || isLowQualityPageTitle(title) || isLowQualityTextSignal(title, { allowSingleWord: true });
  if (titleLowQuality && h1Count === 0 && h2Count === 0) return false;
  return h1Count > 0 || h2Count > 0 || linksCount >= 4 || imagesCount >= 6;
};

const extractSummaryCandidatesFromPayload = (payload = null) => {
  const parsed = payload && typeof payload === "object" ? payload : {};
  const candidates = [];
  const pushCandidate = (summary, sourceUrl = "") => {
    if (!summary || typeof summary !== "object") return;
    candidates.push({
      summary,
      sourceUrl: String(sourceUrl || "").trim(),
    });
  };

  pushCandidate(parsed?.htmlSummary, parsed?.urlUsed || parsed?.site?.url || parsed?.sourceUrl);
  pushCandidate(parsed?.summary, parsed?.url || parsed?.urlUsed || parsed?.sourceUrl);

  const pageSpecs = Array.isArray(parsed?.page_specs) ? parsed.page_specs : [];
  const homeSpec =
    pageSpecs.find((page) => normalizeTemplatePagePath(page?.path || "/") === "/") || pageSpecs[0] || null;
  if (homeSpec?.summary && typeof homeSpec.summary === "object") {
    pushCandidate(homeSpec.summary, homeSpec?.source_url || parsed?.sourceUrl || parsed?.urlUsed || "");
  }

  return candidates;
};

const mergeSummaryWithHistoricalFallback = ({ current = null, historical = null } = {}) => {
  const currentSummary = current && typeof current === "object" ? current : {};
  const historicalSummary = historical && typeof historical === "object" ? historical : {};
  if (!Object.keys(historicalSummary).length) return currentSummary;
  const preferHistorical = isLikelyBlockedHtmlSummary(currentSummary);
  const chooseTextArray = (primary, fallback, limit, options = undefined) => {
    const rows = preferHistorical
      ? [...summaryTextList(fallback), ...summaryTextList(primary)]
      : [...summaryTextList(primary), ...summaryTextList(fallback)];
    return dedupeTextValues(rows, limit, options);
  };
  const chooseLinks = (primary, fallback, limit = 24) => {
    const rows = preferHistorical
      ? [...summaryTextList(fallback), ...summaryTextList(primary)]
      : [...summaryTextList(primary), ...summaryTextList(fallback)];
    return dedupeTextValues(rows, limit, { allowSingleWord: true });
  };
  const chooseUrlList = (primary, fallback, limit) => {
    const rows = preferHistorical
      ? [...(Array.isArray(fallback) ? fallback : []), ...(Array.isArray(primary) ? primary : [])]
      : [...(Array.isArray(primary) ? primary : []), ...(Array.isArray(fallback) ? fallback : [])];
    return dedupeUrls(rows, limit);
  };
  const chooseTitle = () => {
    const currentTitle = String(currentSummary?.title || "").trim();
    if (
      currentTitle &&
      !isLowQualityPageTitle(currentTitle) &&
      !isLowQualityTextSignal(currentTitle, { allowSingleWord: true })
    ) {
      return currentTitle;
    }
    const fallbackTitle = String(historicalSummary?.title || "").trim();
    if (fallbackTitle) return fallbackTitle;
    return currentTitle;
  };

  return {
    ...historicalSummary,
    ...currentSummary,
    title: chooseTitle(),
    h1: chooseTextArray(currentSummary?.h1, historicalSummary?.h1, 12),
    h2: chooseTextArray(currentSummary?.h2, historicalSummary?.h2, 16),
    links: chooseLinks(currentSummary?.links, historicalSummary?.links, 40),
    images: chooseUrlList(currentSummary?.images, historicalSummary?.images, 80),
    footerLinks: dedupeLinkItems(
      preferHistorical
        ? [
            ...(Array.isArray(historicalSummary?.footerLinks) ? historicalSummary.footerLinks : []),
            ...(Array.isArray(currentSummary?.footerLinks) ? currentSummary.footerLinks : []),
          ]
        : [
            ...(Array.isArray(currentSummary?.footerLinks) ? currentSummary.footerLinks : []),
            ...(Array.isArray(historicalSummary?.footerLinks) ? historicalSummary.footerLinks : []),
          ],
      24
    ),
    navMenuDepth: Math.max(Number(currentSummary?.navMenuDepth || 1), Number(historicalSummary?.navMenuDepth || 1)),
    heroPresentation:
      normalizeHeroPresentation(currentSummary?.heroPresentation)?.mode !== "unknown"
        ? normalizeHeroPresentation(currentSummary?.heroPresentation)
        : normalizeHeroPresentation(historicalSummary?.heroPresentation),
    heroCarousel: mergeHeroCarouselSignals([historicalSummary?.heroCarousel, currentSummary?.heroCarousel]),
    sourceSectionHints: mergeSourceSectionHints([historicalSummary?.sourceSectionHints, currentSummary?.sourceSectionHints]),
    sectionComputedStyles: mergeRuntimeSectionComputedStyles([
      currentSummary?.sectionComputedStyles,
      historicalSummary?.sectionComputedStyles,
    ]),
    sectionLayout: mergeRuntimeSectionLayout([
      currentSummary?.sectionLayout,
      historicalSummary?.sectionLayout,
    ]),
    navBackgroundColorRaw:
      String(currentSummary?.navBackgroundColorRaw || "").trim() ||
      String(historicalSummary?.navBackgroundColorRaw || "").trim(),
    footerBackgroundColorRaw:
      String(currentSummary?.footerBackgroundColorRaw || "").trim() ||
      String(historicalSummary?.footerBackgroundColorRaw || "").trim(),
    navBackgroundColor:
      normalizeCssColorToken(currentSummary?.navBackgroundColor || currentSummary?.navBackgroundColorRaw || "") ||
      normalizeCssColorToken(historicalSummary?.navBackgroundColor || historicalSummary?.navBackgroundColorRaw || "") ||
      normalizeColorToken(currentSummary?.navBackgroundColor || "") ||
      normalizeColorToken(historicalSummary?.navBackgroundColor || ""),
    footerBackgroundColor:
      normalizeCssColorToken(currentSummary?.footerBackgroundColor || currentSummary?.footerBackgroundColorRaw || "") ||
      normalizeCssColorToken(historicalSummary?.footerBackgroundColor || historicalSummary?.footerBackgroundColorRaw || "") ||
      normalizeColorToken(currentSummary?.footerBackgroundColor || "") ||
      normalizeColorToken(historicalSummary?.footerBackgroundColor || ""),
    themeColors: dedupeUrls(
      [
        ...(Array.isArray(currentSummary?.themeColors) ? currentSummary.themeColors : []),
        ...(Array.isArray(historicalSummary?.themeColors) ? historicalSummary.themeColors : []),
      ]
        .map((entry) => normalizeColorToken(entry))
        .filter(Boolean),
      20
    ),
    fontFamilies: dedupeTextValues(
      [
        ...(Array.isArray(currentSummary?.fontFamilies) ? currentSummary.fontFamilies : []),
        ...(Array.isArray(historicalSummary?.fontFamilies) ? historicalSummary.fontFamilies : []),
      ]
        .map((entry) => normalizeToCommercialFreeFont(entry, { role: "body" }))
        .filter(Boolean),
      8,
      { allowSingleWord: true }
    ),
    headingFontFamily:
      normalizeToCommercialFreeFont(String(currentSummary?.headingFontFamily || "").trim(), { role: "heading" }) ||
      normalizeToCommercialFreeFont(String(historicalSummary?.headingFontFamily || "").trim(), { role: "heading" }),
    bodyFontFamily:
      normalizeToCommercialFreeFont(String(currentSummary?.bodyFontFamily || "").trim(), { role: "body" }) ||
      normalizeToCommercialFreeFont(String(historicalSummary?.bodyFontFamily || "").trim(), { role: "body" }),
    headingFontPx: Math.max(
      Number(currentSummary?.headingFontPx || 0),
      Number(historicalSummary?.headingFontPx || 0)
    ),
    bodyFontPx: Math.max(
      Number(currentSummary?.bodyFontPx || 0),
      Number(historicalSummary?.bodyFontPx || 0)
    ),
  };
};

const loadHistoricalHtmlSummaryFallback = async ({ siteId, siteUrl = "", currentRunId = "" } = {}) => {
  const normalizedId = slug(siteId || "");
  if (!normalizedId) return null;
  const normalizeOrigin = (value) => {
    const raw = String(value || "").trim();
    if (!raw) return "";
    try {
      return new URL(raw).origin;
    } catch {
      return "";
    }
  };
  const expectedOrigin = normalizeOrigin(siteUrl);
  let entries = [];
  try {
    entries = await fs.readdir(RUNS_DIR, { withFileTypes: true });
  } catch {
    return null;
  }
  const runIds = entries
    .filter((entry) => entry?.isDirectory?.())
    .map((entry) => String(entry.name || "").trim())
    .filter((name) => name && name !== currentRunId)
    .sort((a, b) => b.localeCompare(a));
  const relativeCandidates = [
    "ingest/summary.json",
    "ingest/pages/home/summary.json",
    "extracted/spec-pack.json",
  ];
  for (const runId of runIds) {
    for (const relativePath of relativeCandidates) {
      const filePath = path.join(RUNS_DIR, runId, "sites", normalizedId, relativePath);
      const payload = await readJsonIfExists(filePath);
      if (!payload || typeof payload !== "object") continue;
      const summaryCandidates = extractSummaryCandidatesFromPayload(payload);
      for (const candidate of summaryCandidates) {
        const candidateOrigin = normalizeOrigin(candidate?.sourceUrl || "");
        if (expectedOrigin && candidateOrigin && candidateOrigin !== expectedOrigin) continue;
        if (!isUsableHistoricalHtmlSummary(candidate?.summary)) continue;
        return {
          summary: candidate.summary,
          runId,
          filePath,
        };
      }
    }
  }
  return null;
};

const summarizeRequiredSelection = (pages = []) => {
  const rows = Array.isArray(pages) ? pages : [];
  const roleSet = new Set(
    rows
      .map((row) => String(row?.role || "").trim().toLowerCase())
      .filter(Boolean)
  );
  const count = rows.length;
  const roleCount = roleSet.size;
  // Prefer more required pages first, then better role coverage.
  const score = count * 10 + roleCount;
  return { count, roleCount, score };
};

const injectSyntheticPageSpecRows = ({ siteItem, crawlAssetPack } = {}) => {
  const specPages = Array.isArray(siteItem?.specPack?.page_specs) ? siteItem.specPack.page_specs : [];
  if (!specPages.length) return crawlAssetPack;

  const currentPages = Array.isArray(crawlAssetPack?.pages) ? crawlAssetPack.pages : [];
  const byPath = new Map(
    currentPages.map((row) => [normalizeTemplatePagePath(row?.path || routePathFromUrl(row?.url || "") || "/"), row])
  );
  let injected = 0;
  for (const specPage of specPages) {
    const pathValue = normalizeTemplatePagePath(specPage?.path || "/");
    if (!pathValue || byPath.has(pathValue)) continue;
    const siteUrl = String(siteItem?.site?.url || "").trim();
    let pageUrl = "";
    if (siteUrl) {
      try {
        pageUrl = new URL(pathValue, siteUrl).toString();
      } catch {
        pageUrl = "";
      }
    }
    const synthetic = {
      path: pathValue,
      name: String(specPage?.name || "").trim() || formatTemplatePageName(pathValue),
      url: pageUrl,
      depth: Math.max(0, pathValue.split("/").filter(Boolean).length),
      status: 200,
      summary: {
        title: String(specPage?.name || "").trim() || formatTemplatePageName(pathValue),
        status: 200,
      },
      syntheticFromPageSpec: true,
    };
    byPath.set(pathValue, synthetic);
    injected += 1;
  }
  if (!injected) return crawlAssetPack;
  const mergedPages = Array.from(byPath.values());
  return {
    ...(crawlAssetPack && typeof crawlAssetPack === "object" ? crawlAssetPack : {}),
    pages: mergedPages,
    byPath: new Map(mergedPages.map((row) => [normalizeTemplatePagePath(row?.path || "/"), row])),
    syntheticPageSpecRows: injected,
  };
};

const getImageDimensions = async (filePath) => {
  if (!filePath) return null;
  try {
    const cmd = `/usr/bin/sips -g pixelWidth -g pixelHeight ${JSON.stringify(filePath)}`;
    const { stdout } = await runShell(cmd, { cwd: ROOT });
    const widthMatch = stdout.match(/pixelWidth:\s*(\d+)/);
    const heightMatch = stdout.match(/pixelHeight:\s*(\d+)/);
    const width = Number(widthMatch?.[1] || 0);
    const height = Number(heightMatch?.[1] || 0);
    if (!width || !height) return null;
    return { width, height };
  } catch {
    return null;
  }
};

const createImageSlice = async ({ sourcePath, targetPath, topRatio, heightRatio, leftRatio = 0, widthRatio = 1 }) => {
  const dims = await getImageDimensions(sourcePath);
  if (!dims) return null;
  const cropHeight = Math.max(64, Math.min(dims.height, Math.round(dims.height * heightRatio)));
  const cropWidth = Math.max(64, Math.min(dims.width, Math.round(dims.width * widthRatio)));
  const maxTop = Math.max(0, dims.height - cropHeight);
  const maxLeft = Math.max(0, dims.width - cropWidth);
  const topFromTop = Math.max(0, Math.min(maxTop, Math.round(dims.height * topRatio)));
  const leftFromLeft = Math.max(0, Math.min(maxLeft, Math.round(dims.width * leftRatio)));
  await ensureDir(path.dirname(targetPath));
  const cmd = `python3 - <<'PY'
from PIL import Image
src = ${JSON.stringify(sourcePath)}
dst = ${JSON.stringify(targetPath)}
top = int(${topFromTop})
left = int(${leftFromLeft})
crop_h = int(${cropHeight})
crop_w = int(${cropWidth})
img = Image.open(src)
w, h = img.size
top = max(0, min(h - 1, top))
left = max(0, min(w - 1, left))
bottom = max(top + 1, min(h, top + crop_h))
right = max(left + 1, min(w, left + crop_w))
img.crop((left, top, right, bottom)).save(dst)
PY`;
  await runShell(cmd, { cwd: ROOT });
  return {
    path: targetPath,
    widthPx: cropWidth,
    heightPx: cropHeight,
    topPx: topFromTop,
    leftPx: leftFromLeft,
    sourceWidthPx: dims.width,
    sourceHeightPx: dims.height,
    topRatio,
    heightRatio,
    leftRatio,
    widthRatio,
  };
};

const clampSlicePx = (value, minValue, maxValue) =>
  Math.max(minValue, Math.min(maxValue, Number.isFinite(Number(value)) ? Number(value) : minValue));

const computeAdaptiveSliceRatios = ({ dimensions, mobile = false }) => {
  const width = Number(dimensions?.width || 0);
  const height = Number(dimensions?.height || 0);
  if (!width || !height) return null;
  const aspect = height / Math.max(1, width);
  if (!Number.isFinite(aspect) || aspect < 1.8) return null;

  const navHeight = clampSlicePx(mobile ? 58 : 68, mobile ? 48 : 56, Math.max(mobile ? 64 : 72, Math.floor(height * 0.09)));
  const footerHeight = clampSlicePx(
    mobile ? 260 : 340,
    mobile ? 180 : 220,
    Math.max(mobile ? 220 : 260, Math.floor(height * 0.24))
  );
  const minHero = mobile ? 240 : 300;
  const heroMax = Math.max(minHero, height - navHeight - footerHeight - (mobile ? 220 : 320));
  const heroHeight = clampSlicePx(mobile ? 460 : 560, minHero, heroMax);
  const middleTop = Math.round(navHeight + heroHeight);
  const middleBottom = Math.max(middleTop + (mobile ? 200 : 280), height - footerHeight);
  const middleSpan = Math.max(mobile ? 200 : 280, middleBottom - middleTop);
  const weights = [1.05, 1, 0.95, 0.85, 0.75];
  const weightSum = weights.reduce((sum, value) => sum + value, 0);
  const middleHeights = weights.map((weight, index) => {
    if (index === weights.length - 1) return 0;
    return Math.max(64, Math.round((middleSpan * weight) / weightSum));
  });
  const consumed = middleHeights.reduce((sum, value) => sum + value, 0);
  middleHeights[middleHeights.length - 1] = Math.max(64, middleSpan - consumed);
  const middleTops = [];
  let cursor = middleTop;
  for (const heightValue of middleHeights) {
    middleTops.push(cursor);
    cursor += heightValue;
  }

  const pxToRatio = (px) => Number((Math.max(0, px) / height).toFixed(6));
  return {
    navigation: { top: 0, height: pxToRatio(navHeight) },
    hero: { top: pxToRatio(navHeight), height: pxToRatio(heroHeight) },
    story: { top: pxToRatio(middleTops[0]), height: pxToRatio(middleHeights[0]) },
    approach: { top: pxToRatio(middleTops[1]), height: pxToRatio(middleHeights[1]) },
    products: { top: pxToRatio(middleTops[2]), height: pxToRatio(middleHeights[2]) },
    socialproof: { top: pxToRatio(middleTops[3]), height: pxToRatio(middleHeights[3]) },
    cta: { top: pxToRatio(middleTops[4]), height: pxToRatio(middleHeights[4]) },
    footer: { top: pxToRatio(height - footerHeight), height: pxToRatio(footerHeight) },
  };
};

const buildSectionRatiosFromRuntimeLayout = ({ sectionLayout = null, dimensions = null, mobile = false } = {}) => {
  if (!sectionLayout || typeof sectionLayout !== "object") return null;
  const width = Number(dimensions?.width || 0);
  const height = Number(dimensions?.height || 0);
  if (!width || !height) return null;
  const docHeight =
    Math.max(
      1,
      Math.round(Number(sectionLayout?.documentHeightPx || 0) || 0),
      Math.round(height)
    );
  const ratioForKind = (kind) => {
    const row = sectionLayout?.[kind];
    if (!row || typeof row !== "object") return null;
    const topPx = Number(row?.topPx || 0);
    const heightPx = Number(row?.heightPx || 0);
    const topRatioRaw = Number(row?.topRatio);
    const heightRatioRaw = Number(row?.heightRatio);
    const topRatio = Number.isFinite(topRatioRaw) ? topRatioRaw : topPx / docHeight;
    const heightRatio = Number.isFinite(heightRatioRaw) ? heightRatioRaw : heightPx / docHeight;
    if (!Number.isFinite(heightRatio) || heightRatio < 0.008) return null;
    return {
      top: Number(Math.max(0, Math.min(1, topRatio)).toFixed(6)),
      height: Number(Math.max(0.008, Math.min(1, heightRatio)).toFixed(6)),
    };
  };
  const base = {};
  const accepted = [];
  const minHeightRatioByKind = {
    hero: 0.08,
    story: 0.05,
    approach: 0.06,
    products: 0.06,
    socialproof: 0.03,
    contact: 0.03,
    cta: 0.03,
    footer: 0.04,
    navigation: 0.008,
  };
  const orderedKinds = ["navigation", "hero", "story", "approach", "products", "socialproof", "cta", "footer"];
  for (const kind of orderedKinds) {
    const ratio = ratioForKind(kind);
    if (ratio) base[kind] = ratio;
    if (!ratio) continue;
    const minRatio = Number(minHeightRatioByKind[kind] || 0.01);
    if (ratio.height < minRatio) {
      delete base[kind];
      continue;
    }
    const duplicated = accepted.some(
      (entry) => Math.abs(entry.top - ratio.top) < 0.02 && Math.abs(entry.height - ratio.height) < 0.02
    );
    if (kind !== "navigation" && kind !== "footer" && duplicated) {
      delete base[kind];
      continue;
    }
    accepted.push(ratio);
  }
  const nav = base.navigation || null;
  const footer = base.footer || null;
  if (!nav && !footer && !base.hero) return null;
  const fallbackRatios = computeAdaptiveSliceRatios({ dimensions, mobile }) || {};
  const merged = {
    ...fallbackRatios,
    ...base,
  };
  if (merged.navigation && merged.hero) {
    const navBottom = Number(merged.navigation.top || 0) + Number(merged.navigation.height || 0);
    const heroTop = Number(merged.hero.top || 0);
    if (heroTop < navBottom - 0.005) {
      const heroBottom = heroTop + Number(merged.hero.height || 0);
      const nextTop = Math.max(0, Math.min(0.96, navBottom));
      const nextHeight = Math.max(0.08, Math.min(0.95 - nextTop, heroBottom - nextTop));
      merged.hero = {
        top: Number(nextTop.toFixed(6)),
        height: Number(nextHeight.toFixed(6)),
      };
    }
  }
  if (nav && nav.top + nav.height > 0.18) {
    merged.navigation = fallbackRatios.navigation || { top: 0, height: mobile ? 0.06 : 0.05 };
  }
  if (footer && footer.height > 0.26) {
    merged.footer = fallbackRatios.footer || { top: mobile ? 0.91 : 0.9, height: mobile ? 0.09 : 0.1 };
  }
  return merged;
};

